package android.os; public class Handler { public final java.util.List<Message> timers=new java.util.ArrayList<>(); public final java.util.List<Long> delays=new java.util.ArrayList<>(); public boolean reject; public RuntimeException scheduleFailure; public Runnable onSchedule; public Message obtainMessage(int w) {Message m=new Message();m.what=w;return m;} public boolean sendMessageDelayed(Message m,long delay) {if(onSchedule!=null)onSchedule.run(); if(scheduleFailure!=null)throw scheduleFailure; if(reject)return false;timers.add(m);delays.add(delay);return true;} }
